-- ============================================================
-- PHASE 1: HELPER FUNCTIONS IN public SCHEMA
-- ============================================================

-- Helper: safely read current user ID from session context
CREATE OR REPLACE FUNCTION public.current_user_id()
RETURNS uuid
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
AS $$
DECLARE
  v_id uuid;
BEGIN
  BEGIN
    v_id := current_setting('app.current_user_id', true)::uuid;
  EXCEPTION WHEN others THEN
    RETURN NULL;
  END;
  RETURN v_id;
END;
$$;

-- Helper: check if a user is the owner of a channel
CREATE OR REPLACE FUNCTION public.is_channel_owner(p_channel_id uuid, p_user_id uuid)
RETURNS boolean
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
AS $$
BEGIN
  IF p_user_id IS NULL THEN
    RETURN false;
  END IF;
  RETURN EXISTS (
    SELECT 1
    FROM public.channels
    WHERE id = p_channel_id
      AND owner_id = p_user_id
  );
END;
$$;

-- Helper: check if a user is a moderator of a channel
CREATE OR REPLACE FUNCTION public.is_channel_moderator(p_channel_id uuid, p_user_id uuid)
RETURNS boolean
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
AS $$
BEGIN
  IF p_user_id IS NULL THEN
    RETURN false;
  END IF;
  RETURN EXISTS (
    SELECT 1
    FROM public.channel_moderators
    WHERE channel_id = p_channel_id
      AND user_id = p_user_id
  );
END;
$$;

-- Helper: check if user can moderate (owner OR moderator)
CREATE OR REPLACE FUNCTION public.can_moderate_channel(p_channel_id uuid, p_user_id uuid)
RETURNS boolean
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
AS $$
BEGIN
  IF p_user_id IS NULL THEN
    RETURN false;
  END IF;
  RETURN (
    public.is_channel_owner(p_channel_id, p_user_id)
    OR
    public.is_channel_moderator(p_channel_id, p_user_id)
  );
END;
$$;

SELECT 'Helper functions created successfully' AS result;
"}

