-- ============================================================
-- PHASE 3A: USERS TABLE POLICIES
-- ============================================================

-- Drop any pre-existing policies (idempotent)
DROP POLICY IF EXISTS "users_select_public"   ON public.users;
DROP POLICY IF EXISTS "users_update_own"      ON public.users;
DROP POLICY IF EXISTS "users_delete_own"      ON public.users;

-- SELECT: Anyone can read public profiles (is_public = true)
-- The current user can always read their own profile (even if private)
CREATE POLICY "users_select_public"
  ON public.users
  FOR SELECT
  USING (
    is_public = true
    OR id = public.current_user_id()
  );

-- UPDATE: Users can only modify their own profile
CREATE POLICY "users_update_own"
  ON public.users
  FOR UPDATE
  USING ( id = public.current_user_id() )
  WITH CHECK ( id = public.current_user_id() );

-- DELETE: Users can only delete their own account
CREATE POLICY "users_delete_own"
  ON public.users
  FOR DELETE
  USING ( id = public.current_user_id() );

SELECT 'Users table policies created' AS result;
"}

