-- ============================================================
-- PHASE 3B: CHANNELS TABLE POLICIES
-- ============================================================

DROP POLICY IF EXISTS "channels_select_public"    ON public.channels;
DROP POLICY IF EXISTS "channels_insert_auth"      ON public.channels;
DROP POLICY IF EXISTS "channels_update_owner"     ON public.channels;
DROP POLICY IF EXISTS "channels_delete_owner"     ON public.channels;

-- SELECT: Everyone can read public channels; owner can always read their own channels
CREATE POLICY "channels_select_public"
  ON public.channels
  FOR SELECT
  USING (
    is_public = true
    OR owner_id = public.current_user_id()
  );

-- INSERT: Any authenticated user can create a channel
--         WITH CHECK ensures the inserter sets themselves as owner
CREATE POLICY "channels_insert_auth"
  ON public.channels
  FOR INSERT
  WITH CHECK (
    public.current_user_id() IS NOT NULL
    AND owner_id = public.current_user_id()
  );

-- UPDATE: Only the channel owner can modify channel details
CREATE POLICY "channels_update_owner"
  ON public.channels
  FOR UPDATE
  USING ( owner_id = public.current_user_id() )
  WITH CHECK ( owner_id = public.current_user_id() );

-- DELETE: Only the channel owner can delete the channel
CREATE POLICY "channels_delete_owner"
  ON public.channels
  FOR DELETE
  USING ( owner_id = public.current_user_id() );

SELECT 'Channels table policies created' AS result;
"}

{"query": "
-- ============================================================
-- PHASE 3E: CHANNEL_MODERATORS TABLE POLICIES
-- ============================================================

DROP POLICY IF EXISTS "channel_mods_select_all"    ON public.channel_moderators;
DROP POLICY IF EXISTS "channel_mods_insert_owner"  ON public.channel_moderators;
DROP POLICY IF EXISTS "channel_mods_delete_owner_or_self" ON public.channel_moderators;

-- SELECT: Anyone who can see the channel can see its moderator list
CREATE POLICY "channel_mods_select_all"
  ON public.channel_moderators
  FOR SELECT
  USING (
    EXISTS (
      SELECT 1
      FROM public.channels c
      WHERE c.id = channel_moderators.channel_id
        AND (
          c.is_public = true
          OR c.owner_id = public.current_user_id()
          OR public.is_channel_moderator(c.id, public.current_user_id())
        )
    )
  );

-- INSERT: Only channel owners can add moderators
CREATE POLICY "channel_mods_insert_owner"
  ON public.channel_moderators
  FOR INSERT
  WITH CHECK (
    public.is_channel_owner(channel_moderators.channel_id, public.current_user_id())
  );

-- DELETE: Channel owner can remove any moderator; moderators can remove themselves
CREATE POLICY "channel_mods_delete_owner_or_self"
  ON public.channel_moderators
  FOR DELETE
  USING (
    public.is_channel_owner(channel_moderators.channel_id, public.current_user_id())
    OR (channel_moderators.user_id = public.current_user_id())
  );

SELECT 'Channel moderators table policies created' AS result;
"}

