-- Setup test fixtures
DO $$
DECLARE
  uid1 uuid := '00000000-0000-0000-0000-000000000001';
  uid2 uuid := '00000000-0000-0000-0000-000000000002';
  uid3 uuid := '00000000-0000-0000-0000-000000000003';
  cid1 uuid := '10000000-0000-0000-0000-000000000001';
  cid2 uuid := '10000000-0000-0000-0000-000000000002';
  pid1 uuid := '20000000-0000-0000-0000-000000000001';
  pid2 uuid := '20000000-0000-0000-0000-000000000002';
  cmid uuid := '30000000-0000-0000-0000-000000000001';
BEGIN
  -- Clean up test data
  DELETE FROM public.users WHERE id IN (uid1, uid2, uid3);

  -- Users: uid1=owner, uid2=moderator, uid3=regular user
  INSERT INTO public.users (id, username, email, is_public)
  VALUES
    (uid1, 'test_owner',    'owner@test.com',    true),
    (uid2, 'test_moderator','moderator@test.com', true),
    (uid3, 'test_user',     'user@test.com',      false);

  -- Channels: cid1=public (owned by uid1), cid2=private (owned by uid1)
  INSERT INTO public.channels (id, name, is_public, owner_id)
  VALUES
    (cid1, 'Public Channel',  true,  uid1),
    (cid2, 'Private Channel', false, uid1);

  -- Moderator: uid2 moderates cid1
  INSERT INTO public.channel_moderators (channel_id, user_id)
  VALUES (cid1, uid2);

  -- Posts: pid1 in public channel by uid1, pid2 in public channel by uid3
  INSERT INTO public.posts (id, channel_id, author_id, title, content)
  VALUES
    (pid1, cid1, uid1, 'Owner Post',  'Content by owner'),
    (pid2, cid1, uid3, 'User Post',   'Content by regular user');

  -- Comment: uid3 on pid1
  INSERT INTO public.comments (id, post_id, author_id, content)
  VALUES (cmid, pid1, uid3, 'Test comment by user');

  RAISE NOTICE 'Test fixtures created successfully';
END;
$$;

SELECT 'Test fixtures created' AS result;
"}

